INSERT INTO `i18n_message` (`id`, `language`, `translation`) VALUES
(1, 'en', '🌐 Change language'),
(1, 'ru', '🌐 Сменить язык'),
(1, 'uzk', '🌐 Тилни ўзгартириш'),
(1, 'uzl', '🌐 Tilni oʻzgartirish'),
(2, 'uzk', '🎉 <b>Ассалому алайкум!</b>\r\n\r\n🤖 <b>Maktabgid ботига хуш келибсиз!</b>\r\nБу бот орқали сиз хусусий мактаблар ва боғчалар ҳақида керакли маълумотларни осонгина топишингиз мумкин.\r\n\r\n📍 Локация бўйича изланг\r\n💰 Нархларни солиштиринг\r\n📅 Иш кунлари билан танишинг\r\n\r\nℹ️ <i>Маълумотлар мунтазам янгиланади.</i>\r\n\r\n🧪 Бот ҳозирда <b>тестлаш босқичида</b> — фикрларингиз биз учун муҳим!\r\n\r\n👇 Қуйидаги менюлардан бирини танлаб давом этинг ёки <b>“🤖 Бот ҳақида”</b> тугмасини босинг.\r\n'),
(2, 'uzl', '🎉 <b>Assalomu alaykum!</b>\r\n\r\n🤖 <b>Maktabgid botiga xush kelibsiz!</b>\r\nBu bot orqali siz xususiy maktablar va bog‘chalar haqida kerakli ma’lumotlarni osongina topishingiz mumkin.\r\n\r\n📍 Lokatsiya bo‘yicha izlang\r\n💰 Narxlarni solishtiring\r\n📅 Ish kunlari bilan tanishing\r\n\r\nℹ️ <i>Ma’lumotlar muntazam yangilanadi.</i>\r\n\r\n🧪 Bot hozirda <b>testlash bosqichida</b> — fikrlaringiz biz uchun muhim!\r\n\r\n👇 Maktabgidga kirish📍 tugmasini bosing'),
