INSERT INTO `post` (`id`, `title`, `image`, `sub_text`, `description`, `status`, `view_count`, `created_at`, `updated_at`, `created_by`, `updated_by`, `publish_at`) VALUES
(1, '{\"ru\":\"В Международной школе Invento открылась новая группа для детей в возрасте 5-6 лет. Прием заявок заканчивается 30 апреля.\",\"uzl\":\"Invento xalqaro maktabida 5-6 yoshli bolalar uchun yangi guruh ochildi. Qabul muddati: 30-aprelgacha\"}', '/uploads/iteach/IMG_5600.PNG', '{\"ru\":\"\",\"uzl\":\"\"}', '{\"ru\":\"\",\"uzl\":\"\"}', 1, NULL, '2026-04-15 07:31:44', '2026-04-15 07:33:08', 1, 1, '2026-04-15 12:32:00'),
(2, '{\"ru\":\"20-процентная ежемесячная премия\",\"uzl\":\" 20 foiz miqdorida har oylik ustama\"}', '/uploads/iteach/3bfy0opC5wdCChuEEpcBhqTTvsdA3cYK.jpg', '{\"ru\":\"Начиная с 1 января 2026 года:\\r\\nДля директоров и их заместителей в общеобразовательных средних учебных заведениях будут установлены ежемесячные премии в размере 20 и 10 процентов соответственно от базовых тарифных ставок на основе результатов показателей эффективности (KPI).\",\"uzl\":\"2026-yil 1-yanvardan boshlab:\\r\\nUmumiy oʻrta taʼlim tashkilotlari direktor va uning oʻrinbosarlariga faoliyat samaradorligi koʻrsatkichlari (KPI) natijasiga koʻra bazaviy tarif stavkalariga nisbatan tegishlicha 20 va 10 foiz miqdorida har oylik ustamalar belgilanadi.\"}', '{\"ru\":\"\",\"uzl\":\"\"}', 1, NULL, '2026-04-15 07:34:50', '2026-04-15 07:34:50', 1, 1, '2026-04-15 12:34:00');
