INSERT INTO `vocations` (`id`, `object_id`, `object_type`, `title`, `description`, `requirements`, `type`, `status`, `max_applicants`, `deadline`, `salary_from`, `salary_to`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 175, '', 'Boshlang\'ich sinf ustozi kerak', 'Xususiy maktabimizga yangi ochilayotgan pochemuchka (0-sinflarimiz) uchun ajoyib imkoniyat!\r\n\r\nIsh sharoitlari:\r\n\r\nIsh vaqti: 08:00-17:00; 5/2\r\n\r\nOylik: suhbat asosida\r\n\r\nQulay ish muhiti\r\n\r\nO\'z vaqtida beriladigan oylik maosh (Avans 20-sanada; Oylik 5-sanada)\r\n\r\nBepul tushlik\r\n\r\nMetodik yordam\r\n\r\nRahbarlar tomonidan qo\'llab-quvvatlashlar\r\n\r\nManzil: Sergeli / Qo‘yliq 5-massiv/ Chilonzor  ', 'Kamida 3 yillik ish tajribasi\r\n\r\nPedagogika yo‘nalishida oliy ma’lumot bo‘lsa afzal\r\n\r\nBolalar bilan ishlashni yaxshi ko‘rish\r\n\r\nMas’uliyatlilik va intizom\r\n\r\nYangiliklar qilish sevadigan\r\n\r\nO\'z ishining ustasi\r\n\r\nVazifalar:\r\n\r\nBoshlang‘ich sinf o‘quvchilariga sifatli ta’lim berish\r\n\r\nDarslarni qiziqarli va samarali tashkil etish\r\n\r\nO‘quvchilarning rivojlanishini kuzatib borish\r\n\r\nOta-onalar bilan samalari muloqotni tashkil etish\r\n\r\nSinfda ijobiy muhitni yaratish', 'full_time', 'active', NULL, '2027-04-19', 4000000.00, 7000000.00, 1, 1776141419, 1776918655),
(2, 348, '', 'Ingliz tili o‘qituvchisi', 'Newcastle School ingliz tili o‘qituvchisini ishga taklif qiladi!\r\n\r\nAgar siz ilhom bera olsangiz, ingliz tilini yaxshi bilsangiz va bilim ulashishni yoqtirsangiz — biz sizni kutamiz!\r\n\r\nMoslashuvchan ish grafigi, ahil jamoa va barqaror maosh.\r\n\r\nOylik maosh: 6 000 000 dan 18 000 000 so‘mgacha (qo‘lga tegadigan)\r\nTo‘lovlar: oyiga 1 marta\r\n\r\nIsh tajribasi: 1–3 yil\r\n\r\nBandlik turi: yarim stavka\r\nStajirovka mavjud\r\nRasmiylashtirish: mehnat shartnomasi asosida\r\n\r\nIsh grafigi: 6/1 yoki 3/3\r\nIsh soatlari: 6 yoki 12 soat\r\n\r\nIsh formati: ish beruvchi joyida (offline)', '• Rus tilini C1+ darajada bilish\r\n• Ingliz tili darajasi — IELTS 7.0 va undan yuqori\r\n• Rus va o‘zbek tillarini bilish\r\n• Kamida 1 yil o‘qituvchilik tajribasi\r\n• Oddiy va tushunarli tushuntira olish\r\n• Vaqtga rioya qilish va mas’uliyatlilik\r\n• Zamonaviy o‘qitish metodikalarini bilish\r\n• Turli yoshdagi o‘quvchilar (o‘smirlar, kattalar) bilan ishlay olish\r\n• O‘rganishga va rivojlanishga tayyorlik\r\n• Zoom, Google Meet va interaktiv platformalarni bilish (afzallik)\r\n• To‘g‘ri og‘zaki va yozma nutq\r\n• Xushmuomalalik, o‘quvchilarni motivatsiya qila olish', 'full_time', 'active', NULL, '2027-04-19', 6000000.00, 18000000.00, 1, 1776141563, 1776918648),
(3, 326, '', 'Ingliz tili o‘qituvchisi', 'Oylik maosh: 10 000 000 dan 12 000 000 so‘mgacha (qo‘lga tegadigan)\r\n\r\nIsh tajribasi: 3–6 yil\r\n\r\nBandlik turi: to‘liq stavka\r\n\r\nIsh grafigi: 5/2\r\n\r\nIsh soatlari: 8 soat\r\n\r\nIsh formati: ish beruvchi joyida (offline)', '• Oliy pedagogik ma’lumot\r\n• Ingliz tili darajasi — kamida C1\r\n• Bolalar bilan ishlash tajribasi ustunlik beradi\r\n• Mas’uliyatlilik, bolalarni yaxshi ko‘rish, ijobiy kayfiyat\r\n• Professional rivojlanish va jamoada ishlashga tayyorlik\r\n\r\nVazifalar:\r\n\r\n• Ingliz tilini o‘qitish (boshlang‘ich yoki o‘rta sinflar — kelishilgan holda)\r\n• O‘quv materiallarini tayyorlash va interaktiv darslar o‘tkazish\r\n• O‘quvchilarning o‘zlashtirish darajasini baholash va hujjatlarni yuritish\r\n• Maktab tadbirlarida, ochiq darslarda va ota-onalar yig‘ilishlarida ishtirok etish\r\n• Jamoa bilan hamkorlik qilish va maktab hayotida faol qatnashish\r\n\r\nBiz taklif qilamiz:\r\n• Ish grafigi: 08:30–17:30, 5/2\r\n• Ish haqi — suhbat davomida kelishiladi\r\n', 'full_time', 'active', NULL, '2027-04-19', 10000000.00, 12000000.00, 1, 1776141735, 1776918637);
